{
  "missionStatement": "Update the repository's research documents with findings from online study and propose new chemistry and physics for room-temperature superconductivity, including new candidate materials, synthesis methods, characterization protocols, and a revised roadmap.",
  "criteria": [
    {
      "description": "Literature review is updated with at least 10 new references from recent publications on room-temperature superconductivity.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "Online research summary document is updated with key findings from online study.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Proposed chemistry and physics document includes a new mechanism for achieving room-temperature superconductivity.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Candidate materials list includes at least 3 new compounds with predicted critical temperatures above 300 K.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Synthesis methods document includes detailed procedures for the new candidate materials.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Characterization techniques document includes protocols for verifying room-temperature superconductivity.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Novel mechanism document describes a new theoretical model for room-temperature superconductivity.",
      "expectedFiles": ["docs/novel_mechanism.md"]
    },
    {
      "description": "Experimental protocol for hydride synthesis is updated with new parameters based on recent research.",
      "expectedFiles": ["docs/experimental_protocol_hydride.md"]
    },
    {
      "description": "Manufacturing scalability document outlines steps for scaling up production of new materials.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Challenges and mitigations document addresses potential issues with new materials and synthesis routes.",
      "expectedFiles": ["docs/challenges_and_mitigations.md"]
    },
    {
      "description": "Experimental feedback loop document describes how to iterate between theoretical predictions and experimental validation.",
      "expectedFiles": ["docs/experimental_feedback_loop.md"]
    },
    {
      "description": "Roadmap is updated with milestones for synthesis, characterization, and testing of new compounds.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Discovery strategy document is updated to incorporate new search methods for candidate materials.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Script predict_tc.py is updated to support prediction for new material types (e.g., hydrides, ternary compounds).",
      "expectedFiles": ["scripts/predict_tc.py"]
    },
    {
      "description": "Database is updated with entries for new candidate materials and their properties.",
      "expectedFiles": ["data/superconductor_database.json"]
    },
    {
      "description": "Unit tests for predict_tc.py are updated to cover new material types.",
      "expectedFiles": ["tests/test_predict_tc.py", "tests/tests_predict_tc.py"]
    },
    {
      "description": "Theoretical framework document is updated to incorporate new models and references.",
      "expectedFiles": ["theoretical_framework.md"]
    }
  ]
}

